# 7) Refresh the exact shared runtime identity using the formula enforced by verify-hash.mjs.
def git_blob_sha(path):
    data=Path(path).read_bytes(); return hashlib.sha1(f'blob {len(data)}\0'.encode()+data).hexdigest()
runtime=['workbook.js','hash.js','workflow-schema.js','workflow-engine.js','prompt-engine.js','response-ingestion.js','project-store.js','app-core.js']
manifest=''.join(f'{f}:{git_blob_sha(f)}\n' for f in runtime)
build='runtime-'+hashlib.sha256(manifest.encode()).hexdigest()[:16]
p=Path('index.html'); s=p.read_text(); s,n=re.subn(r'(<script defer src="(?:workbook|hash|workflow-schema|workflow-engine|prompt-engine|response-ingestion|project-store|app-core)\.js\?v=)[^\"]+(\"></script>)',lambda m:m.group(1)+build+m.group(2),s)
if n!=8: raise SystemExit(f'Expected 8 runtime script tokens; found {n}')
p.write_text(s)
